import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;
import java.io.BufferedReader;
import java.util.Comparator;
import java.util.Collections;
import java.io.InputStream;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskF solver = new TaskF();
        solver.solve(1, in, out);
        out.close();
    }
    static class TaskF {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int MOD = 1_000_000_007;
            // Use 1D arrays for current and next row
            int[] cur1 = new int[N+1];
            int[] cur2 = new int[N+1];
            int[] next1 = new int[N+1];
            int[] next2 = new int[N+1];

            // Initialize next row for x = N (all zeros already)
            // Iterate x from N down to 0
            for (int x = N; x >= 0; --x) {
                // For each x, compute current row from y = N down to 0
                for (int y = N; y >= 0; --y) {
                    int d1 = 0, d2 = 0;
                    // Use next row for x+1, and current row for y+1 (already computed)
                    if (x+1 <= N) {
                        int m = Math.max(next1[y], next2[y]);
                        d2 += m;
                    }
                    d2 %= MOD;
                    if (y+1 <= Math.min(x, N)) {
                        int m = Math.max(cur1[y+1], cur2[y+1]);
                        d2 += m;
                    }
                    d2 %= MOD;

                    if (x+1 <= N) {
                        int m = Math.max(next1[y], next2[y]);
                        d1 = Math.max(d1, 1 + d2 - m + next2[y]);
                        d1 %= MOD;
                        if (d1 < 0) d1 += MOD;
                    }
                    if (y+1 <= Math.min(x, N)) {
                        int m = Math.max(cur1[y+1], cur2[y+1]);
                        d1 = Math.max(d1, 1 + d2 - m + cur2[y+1]);
                        d1 %= MOD;
                        if (d1 < 0) d1 += MOD;
                    }
                    d1 %= MOD;
                    if (d1 < 0) d1 += MOD;
                    d2 %= MOD;
                    if (d2 < 0) d2 += MOD;

                    cur1[y] = d1;
                    cur2[y] = d2;
                }
                // After finishing row x, swap: current becomes next for next iteration (x-1)
                int[] temp1 = next1;
                next1 = cur1;
                cur1 = temp1;
                int[] temp2 = next2;
                next2 = cur2;
                cur2 = temp2;
                // Note: after swap, cur1/cur2 now hold the old next (which is row x+1) but we will overwrite them in next iteration
                // Actually, we need to reset cur1/cur2 for the next x? They will be overwritten when we compute the new row.
                // But careful: after swapping, cur1/cur2 become the old next arrays (which are now unused), and next1/next2 become the just computed row.
                // For the next iteration (x-1), we need next1/next2 to be the row we just computed (x), and cur1/cur2 to be overwritten.
                // So the swap is correct.
            }
            // After loop, the row for x=0 is stored in next1/next2? Actually, after the last iteration (x=0), we computed cur1/cur2 for x=0, then swapped, so next1/next2 become the row for x=0.
            int ans = Math.max(next1[0], next2[0]);

            out.print("" + ans);
            out.println();
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
